import { readFileSync } from "node:fs";
import path from "node:path";

/**
 * Hadith data, read from src/data/hadith/ (generated by scripts/import-hadith.mjs, which runs before build).
 * Synchronous reads keep pages prerendered under Cache Components.
 */
const DATA_DIR = path.join(process.cwd(), "src", "data", "hadith");

export type HadithSection = { id: number; title: string; count: number; first: number; last: number };

export type HadithBookData = {
  slug: string;
  name: string;
  total: number;
  graded: boolean;
  missing: { ar: number; en: number; ur: number };
  sections: HadithSection[];
};

export type Hadith = {
  /** Hadith number in this edition (can be fractional, e.g. 1.1). */
  n: number;
  /** Number in the Arabic edition. */
  an: number;
  ar: string;
  en: string;
  /** Empty when the Urdu translation is missing from the source. */
  ur: string;
  /** Gradings as [scholar, grade]. */
  g?: [string, string][];
};

/** Display names, in the order books are listed. */
export const hadithBooks = {
  bukhari: {
    en: "Sahih al-Bukhari",
    ar: "صحيح البخاري",
    ur: "صحیح بخاری",
    compiler: { en: "Imam al-Bukhari", ar: "الإمام البخاري", ur: "امام بخاری" },
  },
  muslim: {
    en: "Sahih Muslim",
    ar: "صحيح مسلم",
    ur: "صحیح مسلم",
    compiler: { en: "Imam Muslim", ar: "الإمام مسلم", ur: "امام مسلم" },
  },
  abudawud: {
    en: "Sunan Abi Dawud",
    ar: "سنن أبي داود",
    ur: "سنن ابو داؤد",
    compiler: { en: "Imam Abu Dawud", ar: "الإمام أبو داود", ur: "امام ابو داؤد" },
  },
  tirmidhi: {
    en: "Jami' at-Tirmidhi",
    ar: "جامع الترمذي",
    ur: "جامع ترمذی",
    compiler: { en: "Imam at-Tirmidhi", ar: "الإمام الترمذي", ur: "امام ترمذی" },
  },
  nasai: {
    en: "Sunan an-Nasa'i",
    ar: "سنن النسائي",
    ur: "سنن نسائی",
    compiler: { en: "Imam an-Nasa'i", ar: "الإمام النسائي", ur: "امام نسائی" },
  },
  ibnmajah: {
    en: "Sunan Ibn Majah",
    ar: "سنن ابن ماجه",
    ur: "سنن ابن ماجہ",
    compiler: { en: "Imam Ibn Majah", ar: "الإمام ابن ماجه", ur: "امام ابن ماجہ" },
  },
} as const;

export type HadithBookSlug = keyof typeof hadithBooks;

export function isHadithBook(slug: string): slug is HadithBookSlug {
  return slug in hadithBooks;
}

let books: HadithBookData[] | undefined;

export function getHadithBooks(): HadithBookData[] {
  books ??= JSON.parse(readFileSync(path.join(DATA_DIR, "books.json"), "utf8")) as HadithBookData[];
  return books;
}

export function getHadithBook(slug: string): HadithBookData | undefined {
  return getHadithBooks().find((b) => b.slug === slug);
}

export function getHadithSection(slug: HadithBookSlug, sectionId: number): Hadith[] {
  return JSON.parse(readFileSync(path.join(DATA_DIR, slug, `${sectionId}.json`), "utf8")) as Hadith[];
}

export function bookName(slug: HadithBookSlug, locale: string): string {
  const b = hadithBooks[slug];
  return locale === "ar" ? b.ar : locale === "ur" ? b.ur : b.en;
}

export function compilerName(slug: HadithBookSlug, locale: string): string {
  const c = hadithBooks[slug].compiler;
  return locale === "ar" ? c.ar : locale === "ur" ? c.ur : c.en;
}

/**
 * Chapters are split into reading pages by text size rather than a fixed count: hadith length varies
 * from one line to tens of KB (tafsir chapters), and each page's text is sent twice (HTML + RSC payload).
 * A page closes once its text would pass PAGE_TEXT_BUDGET bytes or it holds PAGE_MAX_HADITH hadith.
 * The first page lives at the chapter URL.
 */
const PAGE_TEXT_BUDGET = 100_000;
const PAGE_MAX_HADITH = 50;

export type HadithPage = { start: number; end: number };

const pagesCache = new Map<string, HadithPage[]>();

/** Index ranges [start, end) into getHadithSection() for each reading page of a chapter. */
export function sectionPages(slug: HadithBookSlug, sectionId: number): HadithPage[] {
  const key = `${slug}/${sectionId}`;
  const cached = pagesCache.get(key);
  if (cached) return cached;
  const hadith = getHadithSection(slug, sectionId);
  const pages: HadithPage[] = [];
  let start = 0;
  let bytes = 0;
  hadith.forEach((h, i) => {
    const size = Buffer.byteLength(h.ar) + Buffer.byteLength(h.en) + Buffer.byteLength(h.ur);
    if (i > start && (bytes + size > PAGE_TEXT_BUDGET || i - start >= PAGE_MAX_HADITH)) {
      pages.push({ start, end: i });
      start = i;
      bytes = 0;
    }
    bytes += size;
  });
  pages.push({ start, end: hadith.length });
  pagesCache.set(key, pages);
  return pages;
}

/** Parses a chapter id from the URL ("0" is valid: some books open with an introduction). */
export function parseChapterId(value: string): number | undefined {
  return /^(0|[1-9]\d{0,3})$/.test(value) ? Number(value) : undefined;
}

/** Every [book, chapter] pair, for prerendering. */
export function allChapters(): { book: HadithBookSlug; section: HadithSection }[] {
  return getHadithBooks().flatMap((b) =>
    isHadithBook(b.slug) ? b.sections.filter((s) => s.title).map((section) => ({ book: b.slug as HadithBookSlug, section })) : [],
  );
}

/** URL path (without locale) of a chapter page; page 1 is the chapter URL itself. */
export function chapterPath(book: HadithBookSlug, chapter: number, page = 1): string {
  return page > 1 ? `/hadith/${book}/${chapter}/page/${page}` : `/hadith/${book}/${chapter}`;
}

export type GradeTone = "sound" | "good" | "weak" | "other";

/**
 * Rough colour group for a grading string, for decoration only: the grade text itself is always shown.
 * The source has ~1,650 distinct strings ("Hasan Sahih", "Daif Isnaad", "Sahih - Agreed Upon", ...).
 */
export function gradeTone(grade: string): GradeTone {
  const g = grade.toLowerCase();
  if (/da'?if|munkar|mawdu|shadh|matruk/.test(g)) return "weak";
  if (g.includes("sahih")) return "sound";
  if (g.includes("hasan")) return "good";
  return "other";
}
